import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"否之匪人","description":"周易集解 - 否之匪人","frontmatter":{"title":"否之匪人","description":"周易集解 - 否之匪人"},"headers":[],"relativePath":"zh/classics/jijie/012.md","filePath":"zh/classics/jijie/012.md"}'),l={name:"zh/classics/jijie/012.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="否之匪人" tabindex="-1">否之匪人 <a class="header-anchor" href="#否之匪人" aria-label="Permalink to “否之匪人”">​</a></h1><h2 id="否之匪人-1" tabindex="-1">否之匪人 <a class="header-anchor" href="#否之匪人-1" aria-label="Permalink to “否之匪人”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>否之匪人，不利君子貞，大往小來。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：物不可以終通，故受之以否。</p><p>崔憬曰：物極則反，故不終通而否矣，所謂城復於隍者也。</p><p>虞翻曰：陰消乾，又反泰也。謂三。比坤滅乾，以臣弒其君，子弒其父，故曰匪人。陰來滅陽，君子道消，故不利君子貞。陰信陽詘，故大往小來。則是天地不交而萬物不通，與比三同義也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：否之匪人，不利君子貞。大往小來，則是天地不交而萬物不通也。上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子。小人道長，君子道消也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>崔憬曰：否，不通也。於不通之時，小人道長，故雲匪人。君子道消，故不利君子貞也。</p><p>蜀才曰：此本乾卦。大往，陽往而消。小來，陰來而息也。</p><p>何妥曰：此明天道否也。</p><p>何妥曰：此明人事否也。泰中言志同，否中雲無邦者，言人志不同，必致離散，而亂邦國。</p><p>崔憬曰：君臣乖阻，取亂之道，故言無邦。</p><p>崔憬曰：陰柔，謂坤。陽剛，謂乾也。</p><p>崔憬曰：君子在野，小人在位之義也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天地不交，否。君子以儉德闢難，不可榮以祿。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：天地不交，猶君臣不接。天氣上升，而不下降；地氣沉下，又不上升。二氣特隔，故雲否也。</p><p>虞翻曰：君子謂乾，坤為營，乾為祿，難謂坤為弒君，故以儉德闢難。巽為入伏，乾為遠，艮為山，體遯象，謂闢難遠遁入山，故不可營以祿。營，或作榮。儉，或作險。</p><p>孔潁達曰：言君子於此否時，以節儉為德，闢其危難，不可榮華其身，以居祿位。若據諸侯公卿而言，是闢時群小之難，不可重受官爵也。若據王者言之，謂節儉為德，闢陰陽厄運之難，不可自重榮貴而驕逸也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，拔茅茹以其彙，貞吉，亨。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>荀爽曰：拔茅茹，取其相連，彙者，類也。合體同包，調坤三爻同類相遭，欲在下也。貞者，正也。謂正居其所則吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：拔茅貞吉，志在君也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：陰志在下，欲承君也。</p><p>案：初六，巽爻。巽為草木，陽爻為木，陰爻為草。初六陰爻，草茅之象也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，包承，小人吉，大人否，亨。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>荀爽曰：二與四同功，為四所包，故曰包承也。小人，二也。謂一爻獨居，間象相承，得繫於陽，故吉也。大人，謂五。乾坤分體，天地否隔，故曰大人否也。二五相應，否義得通，故曰「否，亨」矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大人否亨，不亂群也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：否，不也，物三稱群，謂坤三陰亂弒君，大人不從，故不亂群也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，包羞。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：包羞，位不當也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：卦性為否，其義否隔。今以不正，與陽相承，為四所包，違義失正，而可羞者，以位不當故也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，有命，無咎，疇離祉。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>《九家易》曰：巽為命。謂受五之命，以據三陰，故無咎。無命而據，則有咎也。疇者，類也。謂四應初據三，與二同功，故陰類皆離祉也。離，附。祉，福也。陰皆附之，故曰有福。謂下三陰離，受五四之福也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有命無咎，志行也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：謂志行於群陰也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，休否，大人吉。其亡其亡，繫於包桑。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>《九家易》曰：否者消卦，陰欲消陽。故五處和居正，以否絕之。乾坤異體，升降殊隔，卑不犯尊，故大人吉也。</p><p>荀爽曰：陰欲消陽，由四及五，故曰其亡其亡。謂坤性順從，不能消乾使亡。</p><p>荀爽曰：包者，乾坤相包也。桑者，上玄下黃，以象乾坤也。乾職在上，坤體在下，雖欲消乾，繫其本體，不能亡也。</p><p>京房曰：桑有衣食人之功，聖人亦有天覆地載之德，故以喻。</p><p>陸績曰：包，本也。言其堅固不亡，如以巽繩繫也。</p><p>案：其亡其亡，近死之嗟也。其與幾同。幾者，近也。九五居否之時，下包初二。二互坤艮，艮山坤地，地上即田也。五互巽木，田上有木，莫過於桑。如曰「其亡其亡，繫於苞桑」。言五二包繫，根深蒂固，若山之堅，如地之厚者也。雖遭危亂，物莫能害矣。</p><p>鄭玄曰：猶紂囚文王於羑里之獄，四臣獻珍異之物，而終免於難，繫於包桑之謂。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大人之吉，位正當也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>崔憬曰：得位居中也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，傾否，先否後喜。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>侯果曰：傾為覆也。否窮則傾矣。傾猶否，故先否也。傾畢則通，故後喜也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：否終則傾，何可長也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：否終必傾，盈不可久，故先否。下反於初，成益，體震，民說無疆，故後喜。以陰剝陽，故不可久也。</p>',78)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
